package android.text;
public interface InputFilter { CharSequence filter(CharSequence source,int start,int end,Spanned dest,int dstart,int dend); public static class LengthFilter implements InputFilter { private final int max; public LengthFilter(int max){this.max=max;} public int getMax(){return max;} public CharSequence filter(CharSequence source,int start,int end,Spanned dest,int dstart,int dend){int keep=max-(dest.length()-(dend-dstart));if(keep<=0)return "";if(keep>=end-start)return null;int cut=start+keep;if(cut>start && Character.isHighSurrogate(source.charAt(cut-1)))cut--;return source.subSequence(start,cut);} } }
